118: function exportar() {
119:   const aluno = nomeDoAluno();
120:   if (!aluno) {
121:     console.error('O git não sabe o seu nome. Rode de novo com --aluno "Seu Nome".');
122:     process.exit(1);
123:   }
124:   const pasta = path.join(SESSOES, paraPasta(aluno));
125:   fs.mkdirSync(pasta, { recursive: true });
126: 
127:   const lista = extrairJson(executar('opencode', ['session', 'list', '--format', 'json']), '[', ']');
128:   if (lista.length === 0) {
129:     console.error('O OpenCode não tem sessões deste projeto nesta máquina. Rode dentro da pasta do repositório.');
130:     process.exit(1);
131:   }
132: 
133:   let exportadas = 0;
134:   for (const item of lista) {
135:     const destino = path.join(pasta, `${item.id}.json`);
136:     if (lerJson(destino)?.info?.time?.updated === item.updated) continue;
137:     console.log(`exportando ${item.id}  ${item.title}`);
138:     const sessao = compactar(extrairJson(executar('opencode', ['export', item.id]), '{', '}'));
139:     fs.writeFileSync(destino, JSON.stringify(sessao, null, 1));
140:     exportadas++;
141:   }
142:   resumirPasta(pasta, aluno);
143:   console.log(`\n${exportadas} sessão(ões) exportada(s), ${lista.length - exportadas} sem mudança.`);
144:   console.log(`Índice: ${path.relative(process.cwd(), path.join(pasta, 'INDICE.md'))}`);
145: }
146: 
147: // ---------------------------------------------------------------- o que o repositório declara
148: 
149: const comandosDeclarados = umaVez(() =>
150:   (lerJson(path.join(RAIZ, 'projeto.json'))?.testes || []).map(normalizar).filter(Boolean));
151: 
152: const skillsConhecidas = umaVez(() => {
153:   const pasta = path.join(RAIZ, '.opencode', 'skills');
154:   const skills = [];
155:   for (const item of fs.existsSync(pasta) ? fs.readdirSync(pasta) : []) {
156:     const arquivo = path.join(pasta, item, 'SKILL.md');
157:     if (!fs.existsSync(arquivo)) continue;
158:     const texto = fs.readFileSync(arquivo, 'utf8');
159:     const corpo = normalizar(texto.replace(/^---[\s\S]*?\n---/, ''));
160:     const nome = texto.match(/^name:\s*(.+)$/m)?.[1].trim() || item;
161:     if (corpo.length >= 40) skills.push({ nome, corpo });
162:   }
163:   return skills;
164: });
165: 
166: // Skill chamada como comando (/grilling) chega como texto do usuário — o corpo da SKILL.md,
167: // sem marca nenhuma. Só dá para reconhecer comparando com as skills do repositório.
168: function skillDoComando(texto) {
169:   const t = normalizar(texto);
170:   return skillsConhecidas().find((s) => t.startsWith(s.corpo.slice(0, 120)))?.nome ?? null;
171: }
172: 
173: // ---------------------------------------------------------------- documento de requisitos
174: 
175: const TRECHO = 10; // palavras seguidas iguais às do documento contam como colagem
176: 
177: const palavras = (texto) =>
178:   String(texto || '').toLowerCase().replace(/[^\p{L}\p{N}]+/gu, ' ').trim().split(' ').filter(Boolean);
179: 
180: function sequencias(texto) {
181:   const p = palavras(texto);
182:   const todas = new Set();
183:   for (let i = 0; i + TRECHO <= p.length; i++) todas.add(p.slice(i, i + TRECHO).join(' '));
184:   return todas;
185: }
186: 
187: // Sequências de 10 palavras do documento, menos as que também estão no contrato, que o
188: // aluno pode citar à vontade.
189: const sequenciasDoDocumento = umaVez(() => {
190:   if (!DOCUMENTO) return null;
191:   const documento = sequencias(fs.readFileSync(DOCUMENTO, 'utf8'));
192:   const contrato = path.join(RAIZ, 'contrato-api.md');
193:   if (fs.existsSync(contrato)) for (const s of sequencias(fs.readFileSync(contrato, 'utf8'))) documento.delete(s);
194:   return documento;
195: });
196: 
197: // Tamanho, em palavras, do maior trecho do texto que é cópia literal do documento.
198: function maiorTrechoCopiado(texto) {
199:   const documento = sequenciasDoDocumento();
200:   if (!documento) return 0;
201:   const p = palavras(texto);
202:   let maior = 0;
203:   let seguidas = 0;
204:   for (let i = 0; i + TRECHO <= p.length; i++) {
205:     seguidas = documento.has(p.slice(i, i + TRECHO).join(' ')) ? seguidas + 1 : 0;
206:     if (seguidas) maior = Math.max(maior, seguidas + TRECHO - 1);
207:   }
208:   return maior;
209: }
210: 
211: const LE_REQUISITOS =
212:   /\b(cat|type|more|less|head|tail|grep|rg|findstr|get-content|gc|sed|awk|find|ls|dir|pdftotext)\b[^|;&]*requisitos/i;
213: 
214: function agenteLeuRequisitos(ferramenta, entrada) {
215:   if (ferramenta === 'bash') return LE_REQUISITOS.test(entrada.command || '');
216:   if (!['read', 'grep', 'glob', 'list', 'codesearch'].includes(ferramenta)) return false;
217:   return Object.values(entrada).some((valor) => typeof valor === 'string'
218:     && /requisitos/i.test(valor) && !/(^|[\\/])(specs?|entrevistas?)[\\/]/i.test(valor));
219: }
220: 
221: // ---------------------------------------------------------------- análise
222: 
223: const TESTE_CONHECIDO = new RegExp(`\\b(${[
224:   'node\\b[^|;&]*--test',
225:   '(npm|pnpm|yarn|bun)\\s+(run\\s+)?test',
226:   '(bun|deno|go|cargo|dotnet|mix|flutter|dart|rails)\\s+test',
227:   'python[0-9.]*\\s+-m\\s+(pytest|unittest)',
228:   '(mvn|mvnw|gradle|gradlew)(\\.cmd|\\.bat)?\\b[^|;&]*\\btest',
229:   'php\\s+artisan\\s+test',
230:   'vitest|jest|mocha|pytest|phpunit|rspec',
231: ].join('|')})\\b`);
232: // Instalar o pacote de teste, ou citá-lo num commit, não é rodar teste.
233: const NAO_E_TESTE = /\b(install|add|remove|uninstall|require)\b|\b(npm|pnpm|yarn|bun)\s+i\b|\bpub\s+get\b|\bgit\s/;
234: 
235: function ehComandoDeTeste(comando) {
236:   const c = normalizar(comando);
237:   if (!c) return false;
238:   if (comandosDeclarados().some((declarado) => c.includes(declarado))) return true;
239:   return !NAO_E_TESTE.test(c) && TESTE_CONHECIDO.test(c);
240: }
241: 
242: function classificar(arquivo) {
243:   const nome = arquivo.split('/').pop();
244:   if (/(^|\/)(AGENTS|CLAUDE)\.md$/i.test(arquivo) || /(^|\/)\.opencode\//.test(arquivo)) return 'contexto';
245:   if (/(^|\/)entrevistas?\//i.test(arquivo)) return 'entrevista';
246:   if (/(^|\/)auditorias?\//i.test(arquivo)) return 'auditoria';
247:   if (/\.(md|txt)$/i.test(nome)) return /(^|\/)specs?\//i.test(arquivo) || /^spec/i.test(nome) ? 'spec' : 'outro';
248:   if (/(^|\/)(test|tests|__tests__|spec|verificacoes|integration_test)\//i.test(arquivo)) return 'teste';
249:   if (/^test_/i.test(nome) || /[._-](test|tests|spec)\.\w+$/i.test(nome) || /[a-z0-9](Test|Tests|Spec)\.\w+$/.test(nome)) {
250:     return 'teste';
251:   }
252:   return 'código';
253: }
254: 
255: function relativo(arquivo, pastaDaSessao) {
256:   const a = String(arquivo).replace(/\\/g, '/');
257:   const base = String(pastaDaSessao || '').replace(/\\/g, '/').replace(/\/+$/, '');
258:   return base && a.toLowerCase().startsWith(`${base.toLowerCase()}/`) ? a.slice(base.length + 1) : a;
259: }
260: 
261: // Placar de algumas ferramentas de teste. Quando não reconhece, o vermelho e o verde vêm só
262: // do código de saída do processo, que vale para qualquer stack.
263: function placar(saida) {
264:   const t = saida.replace(/\x1b\[[0-9;]*m/g, '');
265:   const n = (x) => Number(x ?? 0);
266:   let m;
267:   const passou = t.match(/^\s*[ℹ#]\s*pass\s+(\d+)/m); // node --test
268:   const falhou = t.match(/^\s*[ℹ#]\s*fail\s+(\d+)/m);
269:   if (passou || falhou) return { ok: n(passou?.[1]), falhou: n(falhou?.[1]) };
270:   if ((m = [...t.matchAll(/\+(\d+)(?:\s+~\d+)?(?:\s+-(\d+))?:\s+(?:All tests passed|Some tests failed)/g)].pop())) {
271:     return { ok: n(m[1]), falhou: n(m[2]) }; // flutter test, dart test
272:   }
273:   if ((m = t.match(/Tests:\s+(?:(\d+) failed, )?(?:\d+ \w+, )*?(\d+) passed/))) return { ok: n(m[2]), falhou: n(m[1]) }; // jest
274:   if ((m = t.match(/Tests\s+(?:(\d+) failed \| )?(\d+) passed/))) return { ok: n(m[2]), falhou: n(m[1]) }; // vitest
275:   if ((m = [...t.matchAll(/^=+ (.*\bin [\d.]+s.*?) =+$/gm)].pop())) { // pytest
276:     return { ok: n(m[1].match(/(\d+) passed/)?.[1]), falhou: n(m[1].match(/(\d+) (?:failed|errors?)/)?.[1]) };
277:   }
278:   if ((m = [...t.matchAll(/Tests run: (\d+), Failures: (\d+), Errors: (\d+)/g)].pop())) { // maven
279:     return { ok: n(m[1]) - n(m[2]) - n(m[3]), falhou: n(m[2]) + n(m[3]) };
280:   }
281:   if ((m = t.match(/Failed:\s+(\d+),\s+Passed:\s+(\d+)/))) return { ok: n(m[2]), falhou: n(m[1]) }; // dotnet
282:   const cargo = [...t.matchAll(/test result: \w+\. (\d+) passed; (\d+) failed/g)];
283:   if (cargo.length) return cargo.reduce((a, c) => ({ ok: a.ok + n(c[1]), falhou: a.falhou + n(c[2]) }), { ok: 0, falhou: 0 });
284:   if ((m = t.match(/OK \((\d+) tests?/))) return { ok: n(m[1]), falhou: 0 }; // phpunit
285:   if ((m = t.match(/Tests: (\d+), Assertions: \d+(?:, Errors: (\d+))?(?:, Failures: (\d+))?/))) {
286:     return { ok: n(m[1]) - n(m[2]) - n(m[3]), falhou: n(m[2]) + n(m[3]) };
287:   }
288:   return null;
289: }
290: 
291: function analisar(sessao) {
292:   const info = sessao.info || {};
293:   const r = {
294:     id: info.id,
295:     titulo: info.title || '(sem título)',
296:     pasta: info.directory || '',
297:     subagente: Boolean(info.parentID),
298:     inicio: info.time?.created,
299:     fim: info.time?.updated,
300:     modelos: new Set(),
301:     requisicoes: 0,
302:     entrada: 0,
303:     saida: 0,
304:     skills: {},
305:     subagentes: {},
306:     vermelhas: 0,
307:     verdes: 0,
308:     ciclos: 0,
309:     nasceuVerde: 0,
310:     juntos: 0,
311:     alertas: { colou: 0, leu: 0, anexou: 0 },
312:     edicoes: { teste: 0, 'código': 0, spec: 0, entrevista: 0, contexto: 0, auditoria: 0, outro: 0 },
313:     eventos: [],
314:   };
315:   // TDD, lido a cada execução de teste a partir do que mudou desde a execução anterior.
316:   let mudouTeste = false;
317:   let mudouCodigo = false;
318:   let aguardandoVerde = false;
319: 
320:   for (const mensagem of sessao.messages || []) {
321:     const m = mensagem.info || {};
322:     if (m.role === 'assistant' && m.modelID) r.modelos.add(`${m.providerID}/${m.modelID}`);
323: 
324:     for (const parte of mensagem.parts || []) {
325:       const quando = parte.state?.time?.start ?? parte.time?.start ?? m.time?.created;
326: 
327:       if (parte.type === 'step-start') r.requisicoes++;
328:       if (parte.type === 'step-finish' && parte.tokens) {
329:         r.entrada += parte.tokens.input || 0;
330:         r.saida += (parte.tokens.output || 0) + (parte.tokens.reasoning || 0);
331:       }
332:       if (m.role === 'user' && parte.type === 'text' && !parte.synthetic
333:           && !/^\s*<system-reminder>/.test(parte.text || '')) {
334:         const comando = skillDoComando(parte.text);
335:         if (comando) {
336:           contar(r.skills, comando);
337:           r.eventos.push({ quando, tipo: 'comando', texto: comando });
338:         } else {
339:           r.eventos.push({ quando, tipo: 'prompt', texto: umaLinha(parte.text, 400) });
340:           const copiado = maiorTrechoCopiado(parte.text);
341:           if (copiado >= TRECHO) {
342:             r.alertas.colou++;
343:             r.eventos.push({ quando, tipo: 'alerta', texto: `o prompt tem ${copiado} palavras seguidas copiadas do documento de requisitos` });
344:           }
345:         }
346:       }
347:       if (m.role === 'user' && parte.type === 'agent') {
348:         r.eventos.push({ quando, tipo: 'menciona', texto: `@${parte.name}` });
349:       }
350:       if (m.role === 'user' && parte.type === 'file') {
351:         const anexo = `${parte.filename || ''} ${parte.source?.path || ''} ${parte.url || ''}`;
352:         if (/requisitos/i.test(anexo)) {
353:           r.alertas.anexou++;
354:           r.eventos.push({ quando, tipo: 'alerta', texto: `documento de requisitos anexado à conversa (${umaLinha(parte.filename || anexo, 80)})` });
355:         }
356:       }
357:       if (parte.type !== 'tool') continue;
358: 
359:       const estado = parte.state || {};
360:       const entrada = estado.input || {};
361: 
362:       if (agenteLeuRequisitos(parte.tool, entrada)) {
363:         r.alertas.leu++;
364:         const alvo = entrada.filePath || entrada.path || entrada.pattern || entrada.command || '';
365:         r.eventos.push({ quando, tipo: 'alerta', texto: `o agente acessou o documento de requisitos (${parte.tool}: ${umaLinha(alvo, 100)})` });
366:       }
367: 
368:       if (parte.tool === 'skill') {
369:         const nome = entrada.name || '?';
370:         contar(r.skills, nome);
371:         r.eventos.push({ quando, tipo: 'skill', texto: nome });
372:       } else if (parte.tool === 'task') {
373:         const nome = entrada.subagent_type || 'general';
374:         contar(r.subagentes, nome);
375:         const resposta = umaLinha(String(estado.output || '').replace(/<\/?[a-z_]+>/g, ' '), 240);
376:         r.eventos.push({ quando, tipo: 'subagente', nome, descricao: entrada.description || '', resposta });
377:       } else if (['write', 'edit', 'multiedit'].includes(parte.tool) && entrada.filePath) {
378:         const arquivo = relativo(entrada.filePath, r.pasta);
379:         const classe = classificar(arquivo);
380:         r.edicoes[classe]++;
381:         if (classe === 'teste') mudouTeste = true;
382:         if (classe === 'código') mudouCodigo = true;
383:         const anterior = r.eventos[r.eventos.length - 1];
384:         if (anterior && anterior.tipo === 'edita' && anterior.arquivo === arquivo) anterior.vezes++;
385:         else r.eventos.push({ quando, tipo: 'edita', classe, arquivo, vezes: 1 });
386:       } else if (parte.tool === 'bash' && ehComandoDeTeste(entrada.command)) {
387:         const p = placar(String(estado.output ?? estado.metadata?.output ?? ''));
388:         const saidaDoProcesso = estado.metadata?.exit;
389:         const vermelho = (p !== null && p.falhou > 0)
390:           || (typeof saidaDoProcesso === 'number' && saidaDoProcesso !== 0)
391:           || estado.status === 'error';
392:         const verde = !vermelho && ((p !== null && p.falhou === 0) || saidaDoProcesso === 0);
393:         if (vermelho) r.vermelhas++;
394:         if (verde) r.verdes++;
395: 
396:         let leitura = '';
397:         if (mudouTeste && mudouCodigo) {
398:           r.juntos++;
399:           aguardandoVerde = false;
400:           leitura = 'teste e código mudaram juntos: não houve vermelho para ver';
401:         } else if (mudouTeste && vermelho) {
402:           aguardandoVerde = true;
403:           leitura = 'teste novo falhando, como deve ser';
404:         } else if (mudouTeste && verde) {
405:           r.nasceuVerde++;
406:           aguardandoVerde = false;
407:           leitura = 'teste novo já nasceu verde';
408:         } else if (mudouCodigo && verde && aguardandoVerde) {
409:           r.ciclos++;
410:           aguardandoVerde = false;
411:           leitura = 'fecha um ciclo vermelho → verde';
412:         }
413:         mudouTeste = false;
414:         mudouCodigo = false;
415:         r.eventos.push({ quando, tipo: 'teste', comando: umaLinha(entrada.command, 80), vermelho, verde, placar: p, leitura });
416:       }
417:     }
418:   }
419:   return r;
420: }
421: 
422: // ---------------------------------------------------------------- escrita
423: 
424: const RELOGIO = new Intl.DateTimeFormat('pt-BR', {
425:   timeZone: 'America/Sao_Paulo', day: '2-digit', month: '2-digit', hour: '2-digit', minute: '2-digit',
426: });
427: const hora = (ms) => (ms ? RELOGIO.format(new Date(ms)).replace(',', '') : '—');
428: const milhar = (n) => n.toLocaleString('pt-BR');
429: const nomes = (contagem) =>
430:   Object.entries(contagem).map(([nome, n]) => (n > 1 ? `${nome} (${n})` : nome)).join(', ') || '—';
431: const alertas = (a) =>
432:   [a.colou && `colou ${a.colou}`, a.leu && `leu ${a.leu}`, a.anexou && `anexou ${a.anexou}`].filter(Boolean).join(' · ') || '—';
433: const celula = (texto) => String(texto).replace(/\|/g, '\\|');
434: 
435: function linhaDoTempo(e) {
436:   const t = `\`${hora(e.quando)}\``;
437:   switch (e.tipo) {
438:     case 'prompt': return `- ${t} **prompt** — ${e.texto}`;
439:     case 'comando': return `- ${t} **/${e.texto}** (skill chamada como comando)`;
440:     case 'menciona': return `- ${t} menciona **${e.texto}**`;
441:     case 'skill': return `- ${t} carrega a skill **${e.texto}**`;
442:     case 'alerta': return `- ${t} **ALERTA** — ${e.texto}`;
443:     case 'subagente':
444:       return `- ${t} chama o subagente **${e.nome}**${e.descricao ? ` — ${e.descricao}` : ''}`
445:         + (e.resposta ? `\n  > ${e.resposta}` : '');
446:     case 'edita':
447:       return `- ${t} edita ${e.classe} \`${e.arquivo}\`${e.vezes > 1 ? ` (${e.vezes}×)` : ''}`;
448:     case 'teste': {
449:       const cor = e.vermelho ? '**vermelho**' : e.verde ? 'verde' : 'sem resultado';
450:       const conta = e.placar ? ` (${e.placar.ok} passaram${e.placar.falhou ? `, ${e.placar.falhou} falharam` : ''})` : '';
451:       return `- ${t} roda \`${e.comando}\` → ${cor}${conta}${e.leitura ? ` — _${e.leitura}_` : ''}`;
452:     }
453:     default: return '';
454:   }
455: }
456: 
457: function paginaDaSessao(r) {
458:   const pastaCurta = r.pasta.split(/[\\/]/).filter(Boolean).slice(-2).join('/');
459:   const e = r.edicoes;
460:   return [
461:     `# ${r.titulo}`,
462:     '',
463:     '| | |',
464:     '|---|---|',
465:     `| Sessão | \`${r.id}\`${r.subagente ? ' (sessão de subagente)' : ''} |`,
466:     `| Pasta | ${pastaCurta || '—'} |`,
467:     `| Período | ${hora(r.inicio)} → ${hora(r.fim)} |`,
468:     `| Modelo | ${[...r.modelos].join(', ') || '—'} |`,
469:     `| Requisições ao modelo | ${r.requisicoes} |`,
470:     `| Tokens de entrada / saída | ${milhar(r.entrada)} / ${milhar(r.saida)} |`,
471:     `| Skills | ${nomes(r.skills)} |`,
472:     `| Subagentes | ${nomes(r.subagentes)} |`,
473:     `| Execuções de teste | ${r.vermelhas} vermelhas, ${r.verdes} verdes |`,
474:     `| TDD | ${r.ciclos} ciclo(s) vermelho → verde · ${r.nasceuVerde} teste(s) que já nasceram verdes · ${r.juntos} vez(es) teste e código juntos |`,
475:     `| Arquivos editados | ${e.teste} de teste, ${e['código']} de código, ${e.entrevista} de entrevista, ${e.spec} de spec, ${e.contexto} de contexto, ${e.auditoria} de auditoria |`,
476:     `| Alertas | ${alertas(r.alertas)} |`,
477:     '',
478:     '## Linha do tempo',
479:     '',
480:     ...r.eventos.map(linhaDoTempo),
481:     '',
482:   ].join('\n');
483: }
484: 
485: function somar(sessoes) {
486:   const t = {
487:     sessoes: sessoes.length, requisicoes: 0, vermelhas: 0, verdes: 0, ciclos: 0, nasceuVerde: 0, juntos: 0,
488:     alertas: { colou: 0, leu: 0, anexou: 0 }, skills: {}, subagentes: {},
489:   };
490:   for (const s of sessoes) {
491:     for (const campo of ['requisicoes', 'vermelhas', 'verdes', 'ciclos', 'nasceuVerde', 'juntos']) t[campo] += s[campo];
492:     for (const campo of Object.keys(t.alertas)) t.alertas[campo] += s.alertas[campo];
493:     for (const [k, n] of Object.entries(s.skills)) t.skills[k] = (t.skills[k] || 0) + n;
494:     for (const [k, n] of Object.entries(s.subagentes)) t.subagentes[k] = (t.subagentes[k] || 0) + n;
495:   }
496:   return t;
497: }
498: 
499: const LEGENDA = [
500:   'Cada execução de teste é lida pelo que mudou desde a anterior:',
501:   '',
502:   '- **Ciclo** — vermelho logo depois de mexer só em teste, e depois verde logo depois de mexer só em código. É o TDD.',
503:   '- **Nasceu verde** — verde logo depois de mexer só em teste. Ou o comportamento já existia, ou o teste não testa o que diz.',
